-- Create KOL table
CREATE TABLE IF NOT EXISTS "Kol" (
    "KolID" BIGSERIAL PRIMARY KEY,
    "UserProfileID" BIGINT NOT NULL,
    "Language" VARCHAR(50),
    "Education" VARCHAR(255),
    "ExpectedSalary" BIGINT,
    "ExpectedSalaryEnable" BOOLEAN DEFAULT false,
    "ChannelSettingTypeID" BIGINT,
    "IDFrontURL" VARCHAR(500),
    "IDBackURL" VARCHAR(500),
    "PortraitURL" VARCHAR(500),
    "RewardID" BIGINT,
    "PaymentMethodID" BIGINT,
    "TestimonialsID" BIGINT,
    "VerificationStatus" BOOLEAN DEFAULT false,
    "Enabled" BOOLEAN DEFAULT true,
    "ActiveDate" TIMESTAMP,
    "Active" BOOLEAN DEFAULT true,
    "CreatedBy" VARCHAR(100),
    "CreatedDate" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "ModifiedBy" VARCHAR(100),
    "ModifiedDate" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "IsRemove" BOOLEAN DEFAULT false,
    "IsOnBoarding" BOOLEAN DEFAULT false,
    "Code" VARCHAR(100),
    "PortraitRightURL" VARCHAR(500),
    "PortraitLeftURL" VARCHAR(500),
    "LivenessStatus" BOOLEAN DEFAULT false
);

